typedef long long ll;

static int cmp_ll(const void *a, const void *b) {
    ll x = *(const ll *)a;
    ll y = *(const ll *)b;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

/*
We need, for each starting oasis, decide whether all oases can be visited.

Key observation:
On a line, to visit all oases starting from x_i, it is enough to eventually cover
the whole interval [x_1, x_n].

A jump can move to any point, but halves current water. Since refill is available
at every visited oasis, the only meaningful use of jumps is to "switch side":
while clearing one side from a starting oasis, water after refill is always V at
each oasis, so walking between consecutive oases is possible iff each such gap <= V.
To reach the opposite side, one may jump at some moment; after jumping, remaining
water is at most V/2, so from the landing point to the next oasis on that side one
must be within V/2, and then after reaching/refilling, continue walking with full V.

Thus starting at x_i is feasible iff:
- all gaps on the left segment [1..i] are <= V
- all gaps on the right segment [i..n] are <= V
- and at least one of:
    * can clear left side and then jump to within V/2 of the right side:
      x_{i+1} - x_1 <= V/2   (if i<n)
    * can clear right side and then jump to within V/2 of the left side:
      x_n - x_{i-1} <= V/2   (if i>1)
Special cases:
- if i=1 or i=n, no side switch is needed; only need all gaps on the whole line <= V.
- if n=1, always yes.

We precompute whether prefixes/suffixes have all consecutive gaps <= V.
*/

int main(void) {
    int N;
    ll V;
    if (scanf("%d %lld", &N, &V) != 2) return 0;

    ll *x = (ll *)malloc((size_t)N * sizeof(ll));
    for (int i = 0; i < N; ++i) scanf("%lld", &x[i]);

    qsort(x, N, sizeof(ll), cmp_ll);

    if (N == 1) {
        puts("Yes");
        free(x);
        return 0;
    }

    char *pref = (char *)malloc((size_t)N);
    char *suff = (char *)malloc((size_t)N);

    pref[0] = 1;
    for (int i = 1; i < N; ++i) {
        pref[i] = pref[i - 1] && (x[i] - x[i - 1] <= V);
    }

    suff[N - 1] = 1;
    for (int i = N - 2; i >= 0; --i) {
        suff[i] = suff[i + 1] && (x[i + 1] - x[i] <= V);
    }

    for (int i = 0; i < N; ++i) {
        int ok = 0;

        if (i == 0) {
            ok = suff[0];
        } else if (i == N - 1) {
            ok = pref[N - 1];
        } else {
            if (pref[i] && suff[i]) {
                /* Compare doubled distances to avoid fractions */
                ll need1 = 2 * (x[i + 1] - x[0]);       /* left first, then jump to right */
                ll need2 = 2 * (x[N - 1] - x[i - 1]);   /* right first, then jump to left */
                if (need1 <= V || need2 <= V) ok = 1;
            }
        }

        puts(ok ? "Yes" : "No");
    }

    free(pref);
    free(suff);
    free(x);
    return 0;
}

