    }
    sort(x.begin(), x.end());

    // For each starting oasis, check possibility
    for (int start = 0; start < N; start++) {
        double water = V;
        int l = start, r = start;
        bool possible = true;
        while (l > 0 || r < N - 1) {
            double distLeft = (l > 0) ? x[l] - x[l-1] : 1e18;
            double distRight = (r < N - 1) ? x[r+1] - x[r] : 1e18;
            if (distLeft <= water) {
                water -= distLeft;
                l--;
            } else if (distRight <= water) {
                water -= distRight;
                r++;
            } else {
                // Need to jump
                if (water <= 0) {
                    possible = false;
                    break;
                }
                // Jump reduces water to half
                water /= 2;
                // After jump, we can try again to expand
                // No movement cost for jump itself
            }
            // Safety to avoid infinite loop if stuck
            if (water < min(distLeft, distRight) && water > 0) {
                // Try jumping again
                water /= 2;
            }
            if (water <= 0 && (l > 0 || r < N - 1)) {
                possible = false;
                break;
            }
        }
        cout << (possible ? "Possible" : "Impossible");
        if (start < N - 1) cout << "\n";
