#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    long long V;
    cin >> N >> V;
    vector<long long> x(N);
    for (int i = 0; i < N; ++i) cin >> x[i];

    sort(x.begin(), x.end());

    // Prefix/suffix feasibility for walking only between consecutive oases.
    // L[i] = possible to visit all oases 0..i starting from oasis i (right to left)
    // R[i] = possible to visit all oases i..N-1 starting from oasis i (left to right)
    vector<char> L(N, 0), R(N, 0);
    L[0] = 1;
    for (int i = 1; i < N; ++i) {
        L[i] = L[i - 1] && (x[i] - x[i - 1] <= V);
    }
    R[N - 1] = 1;
    for (int i = N - 2; i >= 0; --i) {
        R[i] = R[i + 1] && (x[i + 1] - x[i] <= V);
    }

    // If starting at i, without any jump it's possible iff both sides are walk-connected.
    // With one jump:
    // - visit one side first, refilling at every oasis, so only consecutive gaps matter.
    // - then jump to the other side (possible to any point, water becomes V/2),
    //   and from there walk through the remaining side, requiring all its consecutive gaps <= V/2.
    //
    // Need prefix/suffix feasibility with threshold V/2 as well.
    long long H = V / 2;

    vector<char> Lh(N, 0), Rh(N, 0);
    Lh[0] = 1;
    for (int i = 1; i < N; ++i) {
        Lh[i] = Lh[i - 1] && (x[i] - x[i - 1] <= H);
    }
    Rh[N - 1] = 1;
    for (int i = N - 2; i >= 0; --i) {
        Rh[i] = Rh[i + 1] && (x[i + 1] - x[i] <= H);
    }

    string ans;
    ans.reserve(N);

    for (int i = 0; i < N; ++i) {
        bool ok = false;

        // No jump: walk all the way on both sides
        if (L[i] && R[i]) ok = true;

        // Visit left side first, then jump to far right and cover right side with V/2
        if (!ok) {
            bool left_done = L[i];
            bool right_after_jump = (i == N - 1) ? true : Rh[i + 1];
            if (left_done && right_after_jump) ok = true;
        }

        // Visit right side first, then jump to far left and cover left side with V/2
        if (!ok) {
            bool right_done = R[i];
            bool left_after_jump = (i == 0) ? true : Lh[i - 1];
            if (right_done && left_after_jump) ok = true;
        }

        ans.push_back(ok ? '1' : '0');
    }

    cout << ans << '\n';
    return 0;
}

