import java.io.*;
import java.util.*;

public class OasesCamel {

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());

        int N = Integer.parseInt(st.nextToken());
        int V = Integer.parseInt(st.nextToken());

        int[] x = new int[N];
        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < N; i++) {
            x[i] = Integer.parseInt(st.nextToken());
        }

        if (N == 1) {
            System.out.println("Possible");
            return;
        }

        // Precompute gaps
        int[] gaps = new int[N - 1];
        for (int i = 0; i < N - 1; i++) {
            gaps[i] = x[i + 1] - x[i];
        }

        // dp[i] = minimal max gap we can cover after processing first i gaps,
        // using some jumps optimally.
        // We'll binary search the answer: can we visit all if max walk distance <= M?

        int lo = 0, hi = V;
        int answer = hi;

        while (lo <= hi) {
            int mid = (lo + hi) / 2;
            if (canCoverAll(N, gaps, V, mid)) {
                answer = mid;
                hi = mid - 1;
            } else {
                lo = mid + 1;
            }
        }

        // Now check from each starting oasis
        boolean[] possibleStart = new boolean[N];
        for (int start = 0; start < N; start++) {
            if (canStartFrom(N, gaps, V, answer, start)) {
                possibleStart[start] = true;
            }
        }

        for (int i = 0; i < N; i++) {
            System.out.println(possibleStart[i] ? "Possible" : "Impossible");
        }
    }

    // Check if we can cover all gaps if max walk allowed is maxWalk
    static boolean canCoverAll(int N, int[] gaps, int V, int maxWalk) {
        // DP: minimal water needed to finish after processing prefix
        int[] dp = new int[N];
        Arrays.fill(dp, Integer.MAX_VALUE / 2);
        dp[0] = 0;

        for (int i = 0; i < N - 1; i++) {
            int g = gaps[i];
            // option 1: walk
            if (g <= maxWalk) {
                for (int j = 0; j <= i; j++) {
                    if (dp[j] < Integer.MAX_VALUE / 2) {
                        int newWater = dp[j] + g;
                        if (newWater <= V) {
                            dp[i + 1] = Math.min(dp[i + 1], newWater);
                        }
                    }
                }
            }
            // option 2: jump at some point before this gap
            // We can simulate by allowing water reset: after jump water = V/2
            // But for feasibility from start, we'll handle in start check
        }
        return dp[N - 1] <= V;
    }

    static boolean canStartFrom(int N, int[] gaps, int V, int maxWalk, int start) {
        // Simulate going left and right from start
        int water = V;
        int pos = start;

        // Try to go left first then right
        int left = start - 1;
        int right = start;

        while (left >= 0 || right < N - 1) {
            boolean moved = false;
            // try walk left
            if (left >= 0 && gaps[left] <= maxWalk && gaps[left] <= water) {
                water -= gaps[left];
                left--;
                moved = true;
            }
            // try walk right
            if (right < N - 1 && gaps[right] <= maxWalk && gaps[right] <= water) {
                water -= gaps[right];
                right++;
                moved = true;
            }
            if (!moved) {
                // try jump if water > 0
                if (water > 0) {
                    water /= 2;
                    // after jump, we can try again
                    continue;
                } else {
                    return false;
                }
            }
        }
        return true;
    }
}

