        Arrays.sort(x);

        if (N == 1) {
            System.out.println("Yes");
            return;
        }

        // Need to know whether there exists some starting oasis from which all can be visited.
        // Since every visited oasis refills to V, moving along the sorted line only requires
        // each consecutive gap to be traversable somehow.
        //
        // A gap g is traversable between adjacent visited parts if:
        // - walk directly: g <= V
        // - or do one jump (to anywhere) then walk: after jump water is V/2, so still need g <= V/2
        //   which is weaker than g <= V, so irrelevant.
        // - or jump across the gap directly: possible regardless of g, but water becomes V/2.
        //   After landing on an oasis, it refills to V.
        //
        // Therefore any adjacent gap can always be crossed using one jump.
        // Starting from any oasis, repeatedly move to neighboring unvisited oasis:
        // for each adjacent gap, either walk if <= V or jump if > V.
        // Since landing on an oasis refills water, all oases are always visitable.
        //
        // Thus answer is always Yes.

        System.out.println("Yes");
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }
